        const n = parseInt(this._taBuffer, 10);
        const commit = () => {
            kind === "hour" ? this._setHour(closestValue(this.hourValues, Math.min(n, 23)), true)
                : this._setMinute(closestValue(this.minuteValues, Math.min(n, 59)), true);
            this._taBuffer = "";
        };
        const mightHaveMoreDigits = kind === "hour" ? n <= 2 : n <= 5;
        if (this._taBuffer.length >= 2 || !mightHaveMoreDigits) commit();
