        this.els.yearBtn.textContent = year;
        const lastDayPrevMonth = new Date(year, month, 0);
        this.els.prev.disabled = !!(this.minDate && lastDayPrevMonth < this.minDate);
        this.els.days.innerHTML = buildDaysHTML({
            view: this.view, today: this.today, selectedDate: this.selectedDate,
            minDate: this.minDate, maxDate: this.maxDate, focusDate: this.focusDate
        });
